llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C26"],
      "claim": "Tropisetron, a tertiary N-methyl tropane ester, showed 52% absolute oral bioavailability after a 20 mg oral dose in healthy volunteers, demonstrating that this tropane ester scaffold can be well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Cocaine, another tertiary N-methyl tropane ester, had an oral bioavailability of 32 ± 4% in volunteers, supporting moderate oral absorption for uncharged tropane esters.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Ipratropium, a quaternary ammonium tropane ester, had only ~2% oral bioavailability, but its permanent positive charge causes poor membrane permeability, a liability absent in the query's tertiary amine.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C03"],
      "claim": "Tiotropium, a quaternary N,N-dimethyl tropane epoxide ester, had 2–3% oral bioavailability; the quaternary charge, rather than the tropane/epoxide scaffold, is the main driver of its poor absorption.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Prediction is high (F ≥ 20%). The query is a tertiary amine tropane ester (scopolamine-like). The most transferable high-F evidence comes from tertiary tropane esters such as tropisetron (52%) and cocaine (~32%), which support moderate-to-good oral bioavailability. The very low F values for ipratropium and tiotropium are explained by their quaternary ammonium charge, which is not present in the query, so those low results do not transfer strongly. Overall, F ≥ 20% is better supported.",
  "evidence_gaps": [
    "No direct human absolute oral bioavailability measurement for the query molecule itself is present in the evidence set.",
    "The exact extent of first-pass metabolism for the query tertiary amine is not directly measured; the true F could be near the 20% threshold.",
    "Transfer from quaternary ammonium analogues is limited by the charge difference, requiring inference rather than direct experimental match."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

